import {diagnosisInput} from './diagnosis-core.js';
const panel=document.createElement('section');panel.className='finding-panel';panel.innerHTML='<div class="card-heading">AI REPAIR PROPOSAL · ON YOUR DEVICE</div><p>Turn captured findings and your source into a repair proposal. Review it, apply your change, and run the task again. <small class="ai-requirements">On-device model · WebGPU · ~1.4 GB first download</small></p><label for="diagnosis-source">Optional source code you own</label><textarea id="diagnosis-source" rows="4" style="width:100%;margin:12px 0" maxlength="6000" placeholder="Paste the relevant control or event handler"></textarea><button class="button primary" id="diagnose">Explain this barrier</button> <button class="button" id="cancel-diagnosis" disabled>Cancel</button><p id="diagnosis-status" role="status" aria-live="polite"></p><pre id="diagnosis-result" style="white-space:pre-wrap"></pre>';
document.querySelector('.takeaway').before(panel);
let report,worker,timeout;const status=document.getElementById('diagnosis-status'),result=document.getElementById('diagnosis-result'),button=document.getElementById('diagnose'),cancel=document.getElementById('cancel-diagnosis');
function stop(){clearTimeout(timeout);worker?.terminate();worker=null;button.disabled=false;cancel.disabled=true;}
document.addEventListener('cif:report',event=>{stop();report=event.detail;result.textContent='';button.disabled=report.outcome==='passed';status.textContent='Selected: '+report.task+' · measured '+report.outcome+(report.outcome==='passed'?'. This journey passed. Explore the checkout barrier for a repair proposal.':'');});
cancel.onclick=()=>{stop();status.textContent='Analysis cancelled. Browser outcome unchanged.';};
button.onclick=()=>{try{const input=diagnosisInput(report,document.getElementById('diagnosis-source').value);result.textContent='';button.disabled=true;cancel.disabled=false;status.textContent='Loading model. Downloads are cached by your browser; first use can take several minutes.';worker=new Worker(new URL('./diagnosis-worker.js',import.meta.url),{type:'module'});timeout=setTimeout(()=>{stop();status.textContent='Analysis timed out. Captured browser evidence remains available.';},600000);worker.onmessage=({data})=>{if(data.type==='progress'){status.textContent='Local model: '+data.status+(Number.isFinite(data.progress)?' '+Math.round(data.progress)+'%':'');return;}stop();if(data.type==='error'){status.textContent='Analysis unavailable: '+data.message;result.textContent=data.raw?'Unvalidated model output (not a diagnosis):\n'+data.raw:'';return;}status.textContent='Repair proposal · browser result: '+data.value.measuredOutcome;result.textContent=JSON.stringify(data.value,null,2);};worker.onerror=()=>{stop();status.textContent='Could not load the local model. Check network access and available memory.';};worker.postMessage({input});}catch(error){status.textContent=error.message;}};
